@once
<style>
.acp-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(100px,.7fr);gap:8px;min-width:0}.acp-fields.acp-single{grid-template-columns:minmax(0,1fr)}
.acp-control{position:relative;min-width:0}.acp-control input{padding-right:38px!important;font-variant-numeric:tabular-nums}.acp-trigger{position:absolute;right:4px;top:4px;bottom:4px;width:30px;border:0;border-radius:6px;background:#F8F8F8;color:#142B49;display:grid;place-items:center}.acp-trigger:hover{background:#EAF0F8}.acp-trigger svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.6}.acp-clear{justify-self:start;border:0;background:none;color:#60738D;font-size:11px;padding:2px 0;grid-column:1/-1}.acp-clear:hover{color:#2563EB;text-decoration:underline}
.acp-panel{position:fixed;inset:auto;margin:0;box-sizing:border-box;width:288px;max-width:calc(100vw - 24px);padding:12px;border:1px solid #DCE4EE;border-radius:14px;background:white;color:#142B49;box-shadow:0 12px 36px #142B4926;z-index:1000;overflow:auto;overscroll-behavior:contain;font-family:inherit;font-size:13px;line-height:1.5}.acp-panel[hidden]{display:none!important}.acp-panel *{box-sizing:border-box}.acp-panel button{font:inherit;border:0;cursor:pointer;color:inherit}.acp-panel button:focus-visible{outline:2px solid #2563EB;outline-offset:-2px}.acp-heading{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:10px}.acp-title{font-size:13px;font-weight:700}.acp-nav{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:transparent;font-size:22px!important}.acp-nav:hover{background:#F0F4F9}.acp-week,.acp-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));text-align:center;gap:2px}.acp-week{color:#60738D;font-size:11px;line-height:26px;margin-bottom:4px}.acp-day{width:100%;aspect-ratio:1;min-height:30px;border-radius:50%;background:transparent;font-variant-numeric:tabular-nums}.acp-day:hover{box-shadow:inset 0 0 0 1px #142B49}.acp-day[aria-current=date]{text-decoration:underline;text-underline-offset:4px;font-weight:700}.acp-day[aria-pressed=true]{background:#2563EB;color:white}.acp-footer{display:flex;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid #E7EDF4;padding-top:9px;margin-top:10px}.acp-footer button{background:#F0F5FF;color:#2563EB;border-radius:7px;padding:6px 10px;font-size:12px}.acp-footer small{color:#60738D;font-size:10px}.acp-time-columns{display:grid;grid-template-columns:1fr 1fr;gap:10px}.acp-time-label{font-size:11px;color:#60738D;text-align:center;margin-bottom:5px}.acp-time-list{height:144px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;border:1px solid #E5EAF2;border-radius:8px;padding:4px;display:flex;flex-direction:column;gap:3px}.acp-time-option{min-height:32px;flex-shrink:0;border-radius:6px;background:transparent;font-variant-numeric:tabular-nums}.acp-time-option:hover{background:#F0F4F9}.acp-time-option[aria-selected=true]{background:#2563EB;color:white}
@media(prefers-reduced-motion:no-preference){.acp-panel:popover-open{animation:acp-enter .12s ease-out}@keyframes acp-enter{from{opacity:.3}to{opacity:1}}}
</style>
@endonce
